def module_level_update(digest, value):
    if isinstance(value, torch.Tensor):
        if value.device.type != "cpu":
            raise ValueError("Expected a CPU sampler output")
        digest.update(str((value.dtype, tuple(value.shape))).encode())
        digest.update(value.contiguous().numpy().tobytes())
    elif isinstance(value, dict):
        for key in sorted(value, key=str):
            module_level_update(digest, key)
            module_level_update(digest, value[key])
    elif isinstance(value, (list, tuple)):
        digest.update(str((type(value).__name__, len(value))).encode())
        for item in value:
            module_level_update(digest, item)
    else:
        digest.update(repr(value).encode())
    digest.update(b"\0")


def module_level_fingerprint(sample):
    digest = hashlib.sha256()
    for field in ("node", "row", "col", "edge", "batch", "num_sampled_nodes", "num_sampled_edges"):
        module_level_update(digest, field)
        module_level_update(digest, getattr(sample, field))
    module_level_update(digest, sample.metadata)
    return digest.hexdigest()

